setStatus.$method:
setStatus(newStatus) {
        this.labStatus = newStatus;
        let labItem = this.labs.find(l => l.id === this.activeLabId);
        if(labItem) labItem.status = newStatus;
        
        let statusNames = {
            'draft': 'DRAFT (Private Sandbox)',
            'published': 'PUBLISHED / SCHEDULED (Visible in Learner Hub UI-04)',
            'active': 'ACTIVE (Live Masterclass Session in UI-09)',
            'inactive': 'INACTIVE / ARCHIVED (Locked for Submissions)'
        };
        this.saveSuccessMsg = `Lab Status updated to ${statusNames[newStatus]}! Department visibility rules updated.`;
        this.saveSuccess = true;
        setTimeout(() => this.saveSuccess = false, 3000);
    }

createNewLabSubmit.$method:
createNewLabSubmit() {
        if(!this.newLab.title) return;
        let newId = 'LAB-BS-0' + (this.labs.length + 1);
        let createdItem = {
            id: newId,
            title: this.newLab.title,
            status: 'draft',
            scoreAvg: 0.0,
            learnersCount: 0,
            pillar: this.newLab.pillar,
            cohort: this.newLab.cohort
        };
        this.labs.push(createdItem);
        this.activeLabId = newId;
        this.labTitle = this.newLab.title;
        this.labCode = this.newLab.code || newId;
        this.pillar = this.newLab.pillar;
        this.cohort = this.newLab.cohort;
        this.accessTier = this.newLab.accessTier;
        this.startDateTime = this.newLab.startDateTime;
        this.endDateTime = this.newLab.endDateTime;
        this.businessContext = this.newLab.context;
        this.selectedDepts = [...this.newLab.depts];
        this.labStatus = 'draft';
        
        this.createModalOpen = false;
        this.saveSuccessMsg = `New Codelab '${createdItem.title}' created in DRAFT state!`;
        this.saveSuccess = true;
        setTimeout(() => this.saveSuccess = false, 3000);
    }

