addVariable.$method:
addVariable() {
        if(this.newVarName) {
            let formattedName = this.newVarName.startsWith('{{') ? this.newVarName : `{{${this.newVarName}}}`;
            this.variables.push({ name: formattedName, description: this.newVarDesc || 'Custom input variable', sample: 'Sample input value' });
            this.newVarName = '';
            this.newVarDesc = '';
        }
    }

