startIngestion.$method:
startIngestion() {
        if (this.activeTab === 'upload_file' && !this.sopTitle) {
            this.sopTitle = 'SOP-Thiet-Ke-Campaign-2026.pdf';
        }
        this.isUploading = true;
        this.uploadProgress = 10;

        let interval = setInterval(() => {
            if (this.uploadProgress < 100) {
                this.uploadProgress += 22;
            } else {
                clearInterval(interval);
                this.isUploading = false;
                this.uploadSuccess = true;

                // Add new document to list
                this.ingestedSops.unshift({
                    id: 'SOP-0' + (this.ingestedSops.length + 1),
                    title: this.sopTitle || 'Google-Drive-SOP-Sync-Context.pdf',
                    type: 'PDF',
                    pages: 8,
                    size: '1.8 MB',
                    dept: this.selectedDept,
                    status: 'synced',
                    lastSync: 'Vừa xong',
                    driveSynced: this.activeTab === 'drive_link'
                });

                setTimeout(() => {
                    this.uploadSuccess = false;
                    this.activeTab = 'manage_sops';
                    this.sopTitle = '';
                    this.driveUrl = '';
                    this.uploadProgress = 0;
                }, 1500);
            }
        }, 300);
    }

